-- Add content column and populate contract sections
ALTER TABLE public.staff_contracts ADD COLUMN IF NOT EXISTS content jsonb;

UPDATE public.staff_contracts SET content = '[{"heading": "SECTION 1 — YOUR DETAILS", "items": []}, {"heading": "SECTION 2 — WHAT THIS AGREEMENT IS", "items": [{"type": "text", "text": "This is a self-employed contractor agreement between you and Active School Org (ASO). It is not an employment contract. You are not an employee of ASO."}, {"type": "text", "text": "This means:"}, {"type": "bullet", "text": "You are responsible for your own tax and National Insurance if applicable"}, {"type": "bullet", "text": "You do not receive sick pay, holiday pay, or a pension from ASO"}, {"type": "bullet", "text": "You are free to work for other organisations unless there is a conflict of interest"}]}, {"heading": "SECTION 3 — YOUR ROLE", "items": [{"type": "text", "text": "Role: Junior Coach. What you do:"}, {"type": "bullet", "text": "Help the Lead Coach during sessions"}, {"type": "bullet", "text": "Set up and pack away equipment"}, {"type": "bullet", "text": "Give out stickers, awards, and help with games"}, {"type": "bullet", "text": "Engage and encourage children during activities"}, {"type": "bullet", "text": "Follow instructions from the Lead Coach at all times"}]}, {"heading": "SECTION 4 — YOUR SESSIONS", "items": [{"type": "text", "text": "You will be assigned to specific schools and sessions as agreed with your Lead Coach."}, {"type": "text", "text": "Typical session length: 45–60 minutes | Sessions per week: 1–5 (as agreed) | Term-time only."}]}, {"heading": "SECTION 5 — YOUR PAY", "items": [{"type": "text", "text": "Pay rate: £10.00 per session attended and completed."}, {"type": "bullet", "text": "Submit your timesheet to Naima by the 5th of each month"}, {"type": "bullet", "text": "Payment is made by bank transfer on the 15th of each month"}, {"type": "bullet", "text": "Late timesheets may result in delayed payment"}, {"type": "text", "text": "Pay queries: email accounts@activeschool.org.uk — do not use WhatsApp."}]}, {"heading": "SECTION 6 — BEFORE YOU START", "items": [{"type": "text", "text": "You cannot attend any session until all of the following are completed:"}]}, {"heading": "SECTION 7 — ABSENCE AND COVER", "items": [{"type": "text", "text": "If you cannot attend a session:"}, {"type": "bullet", "text": "Tell your Lead Coach by phone call or voice note — NOT text — before 9:00am on the day"}, {"type": "bullet", "text": "One unplanned absence per term is acceptable"}, {"type": "bullet", "text": "Two or more in a term will trigger a review"}, {"type": "text", "text": "Planned absences: give at least 7 days'' written notice."}]}, {"heading": "SECTION 8 — ENDING THIS AGREEMENT", "items": [{"type": "text", "text": "Either party can end this agreement by giving two weeks'' written notice. ASO may end it immediately if you breach safeguarding rules, put a child at risk, or damage ASO''s reputation."}]}, {"heading": "SECTION 9 — SAFEGUARDING", "items": []}]'::jsonb WHERE role = 'junior_coach';
UPDATE public.staff_contracts SET content = '[{"heading": "SECTION 1 — YOUR DETAILS", "items": []}, {"heading": "SECTION 2 — WHAT THIS AGREEMENT IS", "items": [{"type": "text", "text": "This is a self-employed contractor agreement between you and Active School Org (ASO). You are not an employee of ASO."}, {"type": "bullet", "text": "You are responsible for your own tax and National Insurance contributions"}, {"type": "bullet", "text": "You do not receive sick pay, holiday pay, or a pension through ASO"}, {"type": "bullet", "text": "You are free to work elsewhere unless it creates a conflict of interest"}]}, {"heading": "SECTION 3 — YOUR ROLE", "items": [{"type": "text", "text": "Role: Assistant Coach. What you do:"}, {"type": "bullet", "text": "Support the Lead Coach in planning and delivering sessions"}, {"type": "bullet", "text": "Lead warm-ups and cool-downs as directed"}, {"type": "bullet", "text": "Support small groups of children during skill activities"}, {"type": "bullet", "text": "Help manage the register and equipment"}, {"type": "bullet", "text": "Follow instructions from the Lead Coach at all times"}]}, {"heading": "SECTION 4 — YOUR SESSIONS", "items": [{"type": "text", "text": "Typical session length: 45–60 minutes | Sessions per week: 1–5 (as agreed) | Term-time only."}]}, {"heading": "SECTION 5 — YOUR PAY", "items": [{"type": "text", "text": "Pay rate: £15.00 per session attended and completed."}, {"type": "bullet", "text": "Submit timesheet to Naima by the 5th of each month"}, {"type": "bullet", "text": "Payment by bank transfer on the 15th of each month"}, {"type": "text", "text": "Pay queries: accounts@activeschool.org.uk — not WhatsApp."}]}, {"heading": "SECTION 6 — BEFORE YOU START", "items": []}, {"heading": "SECTION 7 — ABSENCE AND COVER", "items": [{"type": "bullet", "text": "Contact your Lead Coach by phone call or voice note — NOT text — before 9:00am on the day"}, {"type": "bullet", "text": "One unplanned absence per term is acceptable; two triggers a review; three may end this agreement"}, {"type": "text", "text": "Planned absences: give at least 7 days'' written notice."}]}, {"heading": "SECTION 8 — ENDING THIS AGREEMENT", "items": [{"type": "text", "text": "Either party can end this agreement with two weeks'' written notice. ASO may end it immediately for safeguarding breaches, putting a child at risk, or conduct that damages ASO or the school."}]}, {"heading": "SECTION 9 — SAFEGUARDING", "items": []}]'::jsonb WHERE role = 'assistant_coach';
UPDATE public.staff_contracts SET content = '[{"heading": "SECTION 1 — YOUR DETAILS", "items": []}, {"heading": "SECTION 2 — WHAT THIS AGREEMENT IS", "items": [{"type": "text", "text": "This is a self-employed contractor agreement between you and Active School Org (ASO). You are not an employee of ASO."}, {"type": "bullet", "text": "You are responsible for your own tax and National Insurance contributions"}, {"type": "bullet", "text": "You do not receive sick pay, holiday pay, or a pension through ASO"}, {"type": "bullet", "text": "You are free to work elsewhere unless it creates a conflict of interest with ASO"}]}, {"heading": "SECTION 3 — TERM-TIME WORKING AND WEEKS OFF", "items": [{"type": "text", "text": "School holidays are built-in breaks, not additional ''leave''. Your working schedule already reflects this."}, {"type": "text", "text": "Working weeks: approximately 36 per year | Non-working weeks: approximately 16 per year (school holidays)"}]}, {"heading": "SECTION 4 — YOUR ROLE", "items": [{"type": "text", "text": "Role: Lead Coach. You are responsible for:"}, {"type": "bullet", "text": "Running the full session safely and to ASO standard"}, {"type": "bullet", "text": "Taking and submitting the register at every session"}, {"type": "bullet", "text": "Managing any Assistant Coaches or Junior Coaches in your session"}, {"type": "bullet", "text": "Collecting and safely handing over every child at the end of the session"}, {"type": "bullet", "text": "Completing and submitting session feedback after each session"}, {"type": "bullet", "text": "Reporting any safeguarding concerns, incidents, or behavioural issues"}, {"type": "bullet", "text": "Maintaining a professional relationship with the school"}, {"type": "bullet", "text": "Keeping your First Aid certificate valid and up to date"}]}, {"heading": "SECTION 5 — YOUR SESSIONS", "items": [{"type": "text", "text": "Sessions per week: 1–5 as agreed | Typical length: 45–60 minutes | Term-time only."}, {"type": "text", "text": "You are expected to arrive at least 10 minutes before your session starts."}]}, {"heading": "SECTION 6 — YOUR PAY", "items": [{"type": "text", "text": "Pay rate: £30.00 per session attended and completed."}, {"type": "bullet", "text": "Submit timesheet to Naima by the 5th of each month"}, {"type": "bullet", "text": "Payment by bank transfer on the 15th of each month"}, {"type": "bullet", "text": "Late timesheets delay payment — this cannot be overridden"}, {"type": "text", "text": "Pay queries: accounts@activeschool.org.uk with timesheet attached. Not WhatsApp."}]}, {"heading": "SECTION 7 — BEFORE YOU START", "items": []}, {"heading": "SECTION 8 — ABSENCE AND COVER", "items": [{"type": "text", "text": "Unplanned absence damages the school relationship and lets children down."}, {"type": "bullet", "text": "Contact your Area Lead by phone call or voice note — NOT text — before 9:00am on the day"}, {"type": "bullet", "text": "One unplanned absence per term is acceptable; two triggers a review; three may end this agreement"}, {"type": "text", "text": "Planned absences: give at least 7 days'' written notice."}]}, {"heading": "SECTION 9 — GIVING NOTICE TO LEAVE", "items": [{"type": "text", "text": "Notice must be in writing — email info@activeschool.org.uk or written message to your Area Lead."}, {"type": "text", "text": "ASO reserves the right to withhold payment for uncovered sessions where insufficient notice was the direct cause."}]}, {"heading": "SECTION 10 — ENDING THIS AGREEMENT", "items": [{"type": "text", "text": "ASO may end this agreement immediately if you:"}, {"type": "bullet", "text": "Breach safeguarding guidelines"}, {"type": "bullet", "text": "Put a child at risk through action or inaction"}, {"type": "bullet", "text": "Damage ASO''s or the school''s reputation"}, {"type": "bullet", "text": "Fail to maintain required qualifications (First Aid, DBS)"}, {"type": "bullet", "text": "Consistently underperform after a review process"}]}, {"heading": "SECTION 11 — SAFEGUARDING", "items": [{"type": "text", "text": "Any concern must be recorded and reported on the same day it occurs."}]}]'::jsonb WHERE role = 'lead_coach';
UPDATE public.staff_contracts SET content = '[{"heading": "SECTION 1 — YOUR DETAILS", "items": []}, {"heading": "SECTION 2 — WHAT THIS AGREEMENT IS", "items": [{"type": "text", "text": "This is a self-employed contractor agreement between you and Active School Org (ASO). You are not an employee of ASO."}, {"type": "bullet", "text": "You are responsible for your own tax and National Insurance contributions"}, {"type": "bullet", "text": "You do not receive sick pay, holiday pay, or a pension through ASO"}, {"type": "bullet", "text": "You are free to work elsewhere unless it creates a direct conflict of interest with ASO"}]}, {"heading": "SECTION 3 — TERM-TIME WORKING AND WEEKS OFF", "items": [{"type": "text", "text": "Working weeks: approximately 36 per year | Non-working weeks: approximately 16 per year"}, {"type": "text", "text": "Area Lead hours: up to 4 hours per week during term time (in addition to any Lead Coach sessions you deliver)."}]}, {"heading": "SECTION 4 — YOUR RESPONSIBILITIES", "items": []}, {"heading": "Coach Management", "items": [{"type": "bullet", "text": "First point of contact for all Lead Coaches in your area"}, {"type": "bullet", "text": "Managing cover and absence — never leaving a school without a session or notice"}, {"type": "bullet", "text": "Supporting coach development and identifying progression opportunities"}, {"type": "bullet", "text": "Conducting at least one observation per school per term"}, {"type": "bullet", "text": "Advertising for and interviewing new coaches in your area"}]}, {"heading": "Quality and Standards", "items": [{"type": "bullet", "text": "Monitoring session quality through WhatsApp check-ins and photo updates"}, {"type": "bullet", "text": "Ensuring all coaches follow the ASO session structure"}, {"type": "bullet", "text": "Escalating performance concerns to Naima"}]}, {"heading": "School Relationships", "items": [{"type": "bullet", "text": "Managing any school-level concerns or behavioural issues requiring Area Lead involvement"}, {"type": "bullet", "text": "Maintaining a professional, positive presence with all partner schools"}]}, {"heading": "Administration", "items": [{"type": "bullet", "text": "Ensuring all coaches submit timesheets by the 5th of each month"}, {"type": "bullet", "text": "Submitting your own timesheet on time"}, {"type": "bullet", "text": "Submitting weekly input for the coach newsletter to Naima by Friday 10am"}, {"type": "bullet", "text": "Approving mileage and expenses claims in your area"}]}, {"heading": "Safeguarding", "items": [{"type": "bullet", "text": "You are the Deputy Designated Safeguarding Lead (Deputy DSL) for your area"}, {"type": "bullet", "text": "You must hold a current Level 2 Safeguarding qualification"}, {"type": "bullet", "text": "Any safeguarding concern in your area escalates to you first, then to Naima"}]}, {"heading": "SECTION 5 — YOUR PAY", "items": [{"type": "text", "text": "Area Lead rate: £20.00 per hour (up to 4 hours per week during term time)."}, {"type": "text", "text": "Lead Coach sessions (if delivered): paid separately at £30 per session — log these separately on your timesheet."}, {"type": "bullet", "text": "Submit timesheet by 5th of each month, clearly separating Area Lead hours from coaching sessions"}, {"type": "bullet", "text": "Payment by bank transfer on the 15th of each month"}, {"type": "text", "text": "Pay queries: accounts@activeschool.org.uk — not WhatsApp."}]}, {"heading": "SECTION 6 — QUALIFICATIONS YOU MUST HOLD", "items": []}, {"heading": "SECTION 7 — ABSENCE", "items": [{"type": "text", "text": "If you cannot carry out your Area Lead duties:"}, {"type": "bullet", "text": "Notify Naima by phone call or voice note as early as possible"}, {"type": "bullet", "text": "Ensure cover arrangements are made for any affected sessions before you step back"}, {"type": "bullet", "text": "If unwell for more than 3 consecutive days, notify Naima and agree a temporary plan"}]}, {"heading": "SECTION 8 — GIVING NOTICE TO LEAVE", "items": [{"type": "text", "text": "Notice must be in writing — email info@activeschool.org.uk."}, {"type": "text", "text": "During your notice period you must:"}, {"type": "bullet", "text": "Continue carrying out your Area Lead duties in full"}, {"type": "bullet", "text": "Hand over all school contacts, coach information, and operational notes to Naima or a nominated replacement"}, {"type": "bullet", "text": "Ensure all outstanding timesheets are submitted"}, {"type": "text", "text": "ASO reserves the right to withhold payment for any area disruption caused by insufficient handover."}]}, {"heading": "SECTION 9 — CONFIDENTIALITY", "items": [{"type": "text", "text": "During and after this agreement, you must keep the following confidential:"}, {"type": "bullet", "text": "School contact information and relationships"}, {"type": "bullet", "text": "Coach personal information and pay rates"}, {"type": "bullet", "text": "ASO''s business operations, pricing, and strategy"}, {"type": "bullet", "text": "Any information shared with you in your role that is not public"}, {"type": "text", "text": "This continues to apply after this agreement ends."}]}, {"heading": "SECTION 10 — ENDING THIS AGREEMENT", "items": [{"type": "text", "text": "ASO may end this agreement immediately if you:"}, {"type": "bullet", "text": "Breach safeguarding guidelines or fail to act on a concern"}, {"type": "bullet", "text": "Allow a school to be left without a session through negligence"}, {"type": "bullet", "text": "Damage ASO''s, a school''s, or a family''s trust"}, {"type": "bullet", "text": "Fail to maintain required qualifications"}, {"type": "bullet", "text": "Consistently fail to carry out your responsibilities after a review"}]}]'::jsonb WHERE role = 'area_lead';